import sys
import xml.etree.ElementTree as ET
from io import StringIO

def parse_xml(xml_path):
    tree = ET.parse(xml_path)
    root = tree.getroot()
    items = []
    for item in root.findall('item'):
        items.append({
            'name': item.attrib['name'],
            'value': item.attrib['value']
        })
    return root.attrib['title'], items

def update_items(items, input_lines):
    for line in input_lines:
        if '=' not in line:
            continue
        key, value = line.split('=', 1)
        for item in items:
            if item['name'] == key:
                item['value'] = value
                break

def generate_html(title, items):
    html = f"""<!DOCTYPE html>
<html>
<head><meta charset="utf-8"><title>{title}</title></head>
<body>
<h1>{title}</h1>
<ul>
"""
    for item in items:
        html += f"<li>{item['name']}: {item['value']}</li>\n"
    html += "</ul>\n</body>\n</html>"
    return html

def main():
    if len(sys.argv) != 2:
        print("usage: gen_report.py <config.xml>", file=sys.stderr)
        sys.exit(1)

    xml_path = sys.argv[1]
    title, items = parse_xml(xml_path)

    input_lines = sys.stdin.readlines()
    update_items(items, input_lines)

    with open('report.html', 'w', encoding='utf-8') as f:
        f.write(generate_html(title, items))

if __name__ == "__main__":
    main()
